practice.push(...[{"week": 1, "q": "Which action best demonstrates critical thinking in research?", "options": ["Accepting the most popular explanation", "Checking assumptions and comparing claims with evidence", "Avoiding questions that lack easy answers", "Choosing a result before collecting data"], "correct": 1, "explain": "Critical thinking evaluates assumptions and evidence rather than accepting claims automatically."}, {"week": 1, "q": "Why can a research question change during a project?", "options": ["Because evidence may reveal a better or more precise question", "Because methods never matter", "Because sources should be ignored", "Because conclusions must be fixed in advance"], "correct": 0, "explain": "Research is iterative; new evidence can refine the question."}, {"week": 2, "q": "Which note is most useful when comparing papers?", "options": ["Only the title", "Objective, method, findings, limitations and relevance", "Only the publication colour", "Only the number of pages"], "correct": 1, "explain": "A structured literature matrix supports comparison and synthesis."}, {"week": 2, "q": "What is the best response if two databases return different papers?", "options": ["Assume one database is fraudulent", "Record the search and consider coverage differences", "Delete all results", "Use only the first result"], "correct": 1, "explain": "Scholarly databases differ in coverage and indexing."}, {"week": 3, "q": "Which statement about an outlier is most responsible?", "options": ["Always delete it", "Always keep it without inspection", "Investigate its origin and document the decision", "Change it to the mean"], "correct": 2, "explain": "An unusual value may be an error or a real observation; investigate first."}, {"week": 3, "q": "A model performs well only on the data used to fit it. What should concern you?", "options": ["Whether it generalises to suitable new data", "Whether its title is attractive", "Whether the data has units", "Whether the conclusion is short"], "correct": 0, "explain": "Performance on fitting data alone may not establish predictive validity."}, {"week": 4, "q": "Which is the best slide title?", "options": ["Results", "Graph", "Temperature increased by 12% under condition B", "Figure 2"], "correct": 2, "explain": "A takeaway title communicates the slide’s main message."}, {"week": 4, "q": "What should a technical writer do with a claim from another paper?", "options": ["Copy it without citation", "Cite and accurately represent the source", "Remove its context", "Present it as personal observation"], "correct": 1, "explain": "Claims borrowed from sources need attribution and accurate representation."}, {"week": 5, "q": "Which action may help overcome functional fixedness?", "options": ["Insist on the first interpretation", "Reframe the problem and explore alternate uses", "Avoid brainstorming", "Assume conventional use is mandatory"], "correct": 1, "explain": "Reframing helps expose alternatives."}, {"week": 5, "q": "A researcher obtains a result contrary to the hypothesis. What should happen?", "options": ["Hide the result", "Change the record", "Investigate and report honestly", "Stop documenting experiments"], "correct": 2, "explain": "Research integrity requires honest treatment of unexpected findings."}, {"week": 6, "q": "Before reusing an online figure, what should you check?", "options": ["Only its image resolution", "Its source, licence/permission and applicable conditions", "Whether the colours match", "Whether it has a caption"], "correct": 1, "explain": "Reuse conditions depend on rights and licences; attribution alone may not suffice."}, {"week": 6, "q": "Why are IP categories not interchangeable?", "options": ["They protect different subject matter and rights", "They always have identical duration", "They apply only to research papers", "They eliminate the need for permission"], "correct": 0, "explain": "Different types of intellectual property protect different things."}, {"week": 7, "q": "In DOE, a response is:", "options": ["A controlled input only", "An outcome measured to assess experimental conditions", "A bibliography", "A hypothesis that cannot be measured"], "correct": 1, "explain": "A response is the measured outcome."}, {"week": 7, "q": "Why might factor interactions matter?", "options": ["They mean one factor’s effect may depend on another factor", "They prove the data are false", "They remove all uncertainty", "They make replication impossible"], "correct": 0, "explain": "Interactions describe dependent effects across factor levels."}, {"week": 8, "q": "What is a good first step in interdisciplinary work?", "options": ["Use unexplained jargon", "Define key terms and assumptions", "Assume all fields use the same methods", "Avoid discussing methods"], "correct": 1, "explain": "Explicit terms and assumptions support shared understanding."}, {"week": 8, "q": "What should you take from a research scholar’s experience talk?", "options": ["One anecdote is a universal rule", "How questions, methods and decisions evolved", "That setbacks never occur", "That evidence is optional"], "correct": 1, "explain": "Experience-sharing can illustrate iterative decisions but is not automatically universal."}, {"week": 9, "q": "An AI summary makes a factual claim. What should you do?", "options": ["Cite the AI as proof", "Verify it against the original source", "Assume confidence means accuracy", "Skip reading the source"], "correct": 1, "explain": "AI output must be checked against credible sources."}, {"week": 9, "q": "What is a responsible use of AI during literature discovery?", "options": ["Use suggested keywords to search scholarly databases", "Accept fabricated-looking references", "Upload confidential files without permission", "Skip all primary sources"], "correct": 0, "explain": "AI can assist discovery but primary sources must be checked."}, {"week": 10, "q": "Which is most likely incremental research?", "options": ["A small validated improvement to an existing calibration method", "An unsupported claim of a revolution", "Falsifying a result", "Ignoring previous work"], "correct": 0, "explain": "Incremental work refines an existing line of work."}, {"week": 10, "q": "An imaginative idea becomes a research finding when:", "options": ["It sounds surprising", "It is evaluated using appropriate reasoning and evidence", "It is repeated often", "It is written in bold"], "correct": 1, "explain": "Imagination generates hypotheses; evidence evaluates them."}, {"week": 11, "q": "Why verify generated references?", "options": ["AI never cites sources", "A reference may be inaccurate or nonexistent", "Verification is only for books", "A citation style guarantees truth"], "correct": 1, "explain": "Generated citations may be incorrect or fabricated."}, {"week": 11, "q": "What should a researcher do with sensitive data and AI tools?", "options": ["Check permission and relevant policies before sharing", "Upload everything for convenience", "Remove all context and assume it is safe", "Ignore privacy rules"], "correct": 0, "explain": "Privacy, confidentiality and institutional requirements matter."}, {"week": 12, "q": "What is the best way to handle an MCQ with “always” or “never”?", "options": ["Ignore the qualifier", "Check whether the absolute claim is actually supported", "Select it automatically", "Choose the longest option"], "correct": 1, "explain": "Qualifiers can make an otherwise plausible option too broad."}, {"week": 12, "q": "What should you use to verify an unclear course-specific answer?", "options": ["A guess from memory", "The enrolled course lecture/assignment source", "A random social post", "A different course syllabus"], "correct": 1, "explain": "Course-specific wording should be checked against the enrolled course materials."}]);

