let state={view:'home',selectedWeek:1,cardIndex:0,showAnswer:false,quizMode:'practice',quizItems:[],quizIndex:0,answers:[],answered:false,search:'',archiveWeek:0,cardWeek:0};
const saved=()=>{try{return JSON.parse(localStorage.getItem('rmhub-progress')||'{}')}catch(e){return {}}};let progress=saved();
const content=document.getElementById('content');
function save(){localStorage.setItem('rmhub-progress',JSON.stringify(progress));updateProgress()}
function completedWeeks(){return progress.weeks||[]}
function updateProgress(){let pct=Math.round(completedWeeks().length/12*100);document.getElementById('sideProgress').textContent=pct+'%';document.getElementById('sideProgressBar').style.width=pct+'%'}
function go(view){state.view=view;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('crumbTitle').textContent=({home:'Overview',weeks:'Weekly study plan',flashcards:'Flashcards',assignments:'Assignment archive',quiz:'Practice quiz',notes:'Search notes'})[view]||'Overview';document.getElementById('sidebar').classList.remove('open');render()}
function title(eyebrow,h1,sub){return `<div class="eyebrow">${eyebrow}</div><h1 class="page-title">${h1}</h1><p class="subtitle">${sub}</p>`}
function weekRow(w){let done=completedWeeks().includes(w.n);return `<div class="week-row" data-week="${w.n}"><div class="week-num">${String(w.n).padStart(2,'0')}</div><div><b>${w.title}</b><small>${w.topics.length} topics · ${w.short}</small></div><span class="status-pill ${done?'done':w.n===1?'current':''}">${done?'Completed':w.unverified?'Check coverage':w.n===1?'Start here':'Not started'}</span></div>`}
function home(){let done=completedWeeks().length;return `${`<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR EXAM PREP, IN ONE PLACE</div><h1>By Pavanaj S Achar<br>Make every revision session count.</h1><p>A focused workspace for your NPTEL Research Methodology exam. Move through weekly topics, practise retrieval with flashcards and test yourself before exam day.</p><button class="btn btn-primary" data-action="start">Continue studying <span>→</span></button></div><div class="hero-date"><small>EXAM DATE</small><strong>17 OCT 2026</strong><span>Final stretch · Stay focused</span></div></section>`}
<div class="stats"><div class="stat-card"><div class="stat-top">Weekly modules <span class="stat-icon">▦</span></div><div class="stat-num">12</div><div class="stat-note">8 textbook weeks + later-week archive</div></div><div class="stat-card"><div class="stat-top">Flashcards <span class="stat-icon">▤</span></div><div class="stat-num">${cards.length}</div><div class="stat-note">Review and self-test</div></div><div class="stat-card"><div class="stat-top">Weeks completed <span class="stat-icon">✓</span></div><div class="stat-num">${done}<small style="font:500 12px 'DM Sans';color:#9298a0"> / 12</small></div><div class="stat-note">Saved on this device</div></div><div class="stat-card"><div class="stat-top">Practice questions <span class="stat-icon">◉</span></div><div class="stat-num">${assignmentSample.length}</div><div class="stat-note">Uploaded assignment MCQs</div></div></div>
<div class="section-head"><div><h2>Pick up where you left off</h2><p>Short, deliberate study blocks work better than passive rereading.</p></div><button class="text-btn" data-view="weeks">All 12 weeks ↗</button></div>
<div class="grid-2"><section class="panel"><h3>Weekly learning path</h3><p class="panel-desc">Your next modules, organised in course order.</p><div class="week-list">${weeks.slice(0,4).map(weekRow).join('')}</div><button class="btn btn-light" style="margin-top:13px" data-view="weeks">Browse all weeks →</button></section><section class="panel"><h3>Suggested study session</h3><p class="panel-desc">A practical loop for each study session.</p><div class="task-list"><div class="task"><div class="task-icon">01</div><div><b>Review one week</b><p>Read the topic map and explain each point in your own words.</p></div></div><div class="task"><div class="task-icon">02</div><div><b>Recall without looking</b><p>Use flashcards and revisit the cards you miss.</p></div></div><div class="task"><div class="task-icon">03</div><div><b>Test your understanding</b><p>Attempt a practice set, then inspect explanations.</p><button class="text-btn" data-view="quiz">Start practice quiz →</button></div></div></div><div class="callout"><strong>Coverage note:</strong> your textbook contents list Weeks 1–8. The official course outline includes later-week topics; Week 12 is kept as an assignment archive because its lecture title could not be verified.</div></section></div>
<div class="section-head"><div><h2>Quick access</h2><p>Choose the mode that fits your next 10 minutes.</p></div></div><div class="week-grid"><article class="week-card"><div class="week-card-top"><span class="week-badge">01 / RECALL</span><span>▤</span></div><h3>Flashcard sprint</h3><p>Active recall across all topics. Reveal the answer, then mark what you know.</p><div class="week-card-foot"><button class="btn btn-light" data-view="flashcards">Start flashcards →</button></div></article><article class="week-card"><div class="week-card-top"><span class="week-badge">02 / PRACTISE</span><span>◉</span></div><h3>Mixed practice quiz</h3><p>Answer multiple-choice questions with feedback and a score summary.</p><div class="week-card-foot"><button class="btn btn-light" data-view="quiz">Take quiz →</button></div></article></div>`}
function weeksPage(){return `${title('THE COURSE MAP','Your 12-week study plan','Follow the module sequence. Mark a week complete when you have reviewed its topic map and attempted recall.')}<div class="notice"><b>Source alignment:</b> Weeks 1–8 are listed in your uploaded textbook. The official IIT Madras course outline also lists Weeks 9–11. Your ZIP has Week 1–12 assignment folders; Week 12 is preserved as assignment material without a guessed lecture title. <a href="https://nptel.ac.in/courses/121106007" target="_blank" rel="noreferrer">Official outline ↗</a></div><div class="week-grid">${weeks.map(w=>`<article class="week-card"><div class="week-card-top"><span class="week-badge">WEEK ${String(w.n).padStart(2,'0')}</span><span class="status-pill ${completedWeeks().includes(w.n)?'done':''}">${completedWeeks().includes(w.n)?'Completed':w.unverified?'Archive':''}</span></div><h3>${w.title}</h3><p>${w.short}. ${w.topics.slice(0,3).join(' · ')}${w.topics.length>3?' …':''}</p><div class="tag-row">${w.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><div class="week-card-foot"><button class="btn btn-light" data-open-week="${w.n}">Study week →</button><button class="btn btn-primary" data-mark-week="${w.n}">${completedWeeks().includes(w.n)?'Undo ✓':'Mark done'}</button></div></article>`).join('')}</div>`}
function weekDetail(n){const w=weeks.find(x=>x.n===n);state.selectedWeek=n;const d=(window.weekStudyData||{})[n]||{};const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');const sourceSections=d.sections||[];const topics=w.topics||[];let ti=Math.max(0,Math.min(Number(state.selectedTopicIndex||0),topics.length-1));const topic=topics[ti]||w.title;const topicSectionMap={1:[0,1,2,3,4],2:[0,1,1,3,3,3,6],3:[0,1,2,5,4],4:[0,2],5:[0,1,3,2],6:[0,3],7:[0,1,2,3,4],8:[0,0,1,0,1,0,1,2,0,1,0,1,0,1,2,2,3],9:[0,1,2,3],10:[0,1,2],11:[0,4,3,5],12:[0,3,2]};const mapped=(topicSectionMap[n]||[])[ti];const scoreSection=(t)=>{if(Number.isInteger(mapped))return Math.min(mapped,Math.max(0,sourceSections.length-1));const words=t.toLowerCase().split(/[^a-z0-9]+/).filter(x=>x.length>3);let best=0,bestScore=-1;sourceSections.forEach((sec,i)=>{const hay=(sec[0]+' '+sec[1].join(' ')).toLowerCase();const score=words.reduce((a,x)=>a+(hay.includes(x)?1:0),0);if(score>bestScore){bestScore=score;best=i}});return best};let selectedSection=sourceSections[scoreSection(topic)]||[topic,[w.note||'Review the topic using the course material.'],'Return to the lecture transcript and textbook section for the full treatment.'];const topicExtras={2:{4:['A bibliography stores the publication details needed to identify sources used in a piece of writing.','In Word, enter or import source details carefully, then use the citation/bibliography tools consistently.','Generated formatting is only as accurate as the metadata entered; verify author, title, year and publication details against the source.'],5:['EndNote-style entries connect in-text citations with full reference details.','Keep the numbering/order consistent with the citation style and update references after editing the document.','Check that every cited item appears in the reference list and that unused references are not left in the final list.'],6:['Before an experiment, define the objective, variables, equipment and procedure.','Check calibration, range, units and safety requirements; record conditions and unexpected outcomes.','Repeatability depends on a clear record of what was done, not merely the final result.'],1:['Web of Science is a citation-indexing database used to discover publications and trace citation relationships.','Record the exact query, filters and search date so the search can be repeated.','Use it to identify relevant papers and follow citation links; database coverage is not exhaustive.'],'2':['Scopus is a scholarly abstract and citation database.','Search with related keywords and inspect publication, author and citation records.','Compare results across databases because indexing coverage and search behaviour can differ.']},3:{4:['Laboratory safety begins before work: identify hazards, assess risk and follow the relevant lab procedures and supervision.','Use appropriate protective equipment and check equipment, chemicals and operating limits before starting.','Report incidents and near misses; do not bypass a safety step to save time.']},4:{2:['Technical writing communicates a technical idea accurately and in a structure readers can follow.','Use precise terminology, define specialised terms, support claims with evidence and separate facts from interpretation.','Revise for logical flow, units, figure/table references, citations and consistency—not only spelling.']},5:{2:['Creativity in research includes generating alternative ideas and testing them rather than accepting the first solution.','A useful creative process alternates divergent thinking (producing possibilities) with critical evaluation (checking evidence and feasibility).','A novel idea must still be reported honestly and tested appropriately.']},11:{2:['An experience-sharing session is best studied by extracting the research problem, motivation, method choice, turning point and lessons from setbacks.','Distinguish what the speaker experienced from a general principle that applies to every project.','Ask what evidence or feedback caused the researcher to change direction.'],3:['For a second research-experience discussion, compare the stages of the journey: choosing a question, building skills, handling failed attempts, communicating results and deciding next steps.','Different researchers may use different methods because their questions, resources and disciplines differ.','Summarise the lesson and the context in which it applies instead of memorising a personal anecdote as a universal rule.']},12:{0:['Use the Week 12 screenshots as the authority for the exact assignment wording and options.','Identify whether the question permits multiple answers; inspect qualifiers such as “typically”, “most likely” and “only”.','For each selected option, be able to explain why it fits and why a tempting alternative does not.'],1:['Cross-week revision should connect ideas rather than keep them isolated: literature review helps justify a question; methods produce evidence; analysis supports conclusions; writing and ethics govern communication.','Try explaining the chain from research question to method, data, interpretation and limitations.','Use mixed practice to reveal confusions between similar terms.'],2:['Attempt questions before opening notes to test recall honestly.','Flag uncertain items, finish the set, then return to those questions and read the reasoning.','Use the course text and assignment screenshots to settle exact wording; do not infer missing lecture content from a revision summary.']},8:{0:['Applied mechanics investigates the behaviour of physical systems under forces, motion, deformation or energy transfer.','A research question might ask how a structure or component responds under a specified load.','Methods may include analytical models, numerical simulation and experiments; choose based on the question and available evidence.'],1:['Chemical engineering research often examines processes, transport, reactions, separations and scale-up.','A useful question specifies the material or process, operating conditions and response to be measured.','Model predictions should be checked against experimental or plant data when available.'],2:['Civil engineering research may examine structures, geotechnics, transport, water or infrastructure systems.','Field conditions, safety requirements and variation between sites can strongly affect the design.','A defensible study explains the site/sample, measurement method and limits on generalisation.'],3:['Computer science and engineering research can involve algorithms, systems, data, networks, software or hardware.','A study should define the task, baseline, dataset or test environment and evaluation metric.','Reproducibility improves when code versions, parameters and test conditions are recorded.'],4:['Engineering design research investigates how requirements become concepts, prototypes and evaluated designs.','Trade-offs can include performance, cost, reliability, usability and manufacturability.','A design claim should be supported by explicit criteria and testing rather than appearance alone.'],5:['Humanities and social-science research may interpret texts, histories, institutions, experiences or social patterns.','Methods can include archival analysis, interviews, observation, surveys or close reading, depending on the question.','Explain selection of sources/participants and how interpretation was developed; attend to consent and context where relevant.'],6:['Mechanical engineering research often concerns machines, materials, thermal/fluid systems, manufacturing or dynamics.','Define operating conditions and measurable performance indicators before comparing designs.','Combine models and experiments where appropriate, and state assumptions and uncertainty.'],7:['Metallurgical and materials research relates processing, structure, properties and performance.','A question may compare how composition or processing conditions change a measured material property.','Report sample preparation, test conditions and measurement method because they influence comparisons.'],8:['Ocean engineering research concerns marine environments, offshore systems, ocean structures or related technologies.','Environmental conditions such as waves, currents, depth and corrosion may constrain the investigation.','State the conditions and assumptions used; field measurements and simulations answer different parts of a problem.'],9:['Management-studies research may examine organisations, decisions, markets, people or processes.','A clear study defines its unit of analysis, constructs and evidence source.','Interpret survey, interview or organisational data with attention to sampling, bias and the limits of causal claims.'],10:['Aerospace research may involve flight, propulsion, aerodynamics, structures, control or space systems.','Performance claims depend on specified operating conditions and constraints.','Use appropriate analysis, simulation or test evidence and clearly state the validation range.'],11:['Biotechnology research applies biological systems or processes to investigate or develop products and methods.','A sound question identifies the biological material, intervention/condition and measurable outcome.','Controls, contamination prevention, repeatability and ethical approvals may be essential, depending on the work.'],12:['Chemistry research studies substances, composition, structure, properties and transformations.','A useful investigation specifies reagents/materials, conditions and how the outcome will be measured.','Reproducibility requires recording concentrations, temperatures, instruments and relevant safety controls.'],13:['Electrical-engineering research can cover circuits, electronics, power, communications, control or signal processing.','Define input conditions, system configuration and performance metrics before testing.','Report instrument limits, calibration and noise where they influence the result.'],14:['Mathematics research develops or analyses definitions, structures, proofs, algorithms or quantitative models.','The key evidence may be a logically valid proof, counterexample or rigorous analysis rather than a physical experiment.','State assumptions and definitions precisely; distinguish a conjecture from a proved result.'],15:['Physics research seeks explanations of physical phenomena using theory, measurement and experiment.','A research question identifies the phenomenon, conditions and predicted or measured quantity.','Compare observations with a model while accounting for uncertainty and the model’s valid range.'],16:['Research-scholar discussions can reveal how researchers narrow a question, choose a method and respond to setbacks.','Ask what evidence changed the researcher’s thinking, which assumptions failed and how the next step was chosen.','Treat a scholar’s experience as a case study, not a universal rule: methods vary by discipline and project.']}};const topicExamples={
2:{1:'Example: search Web of Science for a focused phrase, record the query and filters, then inspect relevant records and their citation links.',2:'Example: run a comparable search in Scopus and compare the relevant records; differences may reflect indexing and search behaviour rather than an error.',4:'Example: before submitting a report, verify each Word source entry against the original paper and regenerate the bibliography after editing citations.',5:'Example: after moving paragraphs in a document, update EndNote entries and check that every in-text citation still points to the intended reference.',6:'Example: for a temperature-sensor experiment, note the calibration reference, ambient conditions, sampling interval, units and any readings that look unusual.'},
3:{4:'Example: before using a heated instrument, identify the hazards, inspect the equipment, use the required protective measures and follow the lab’s operating procedure.'},
4:{1:'Example: organise a technical presentation as problem, motivation, method, evidence, interpretation and conclusion; make every figure readable and explain what it demonstrates.'},
5:{2:'Example: if a familiar tool seems useful only for its usual purpose, deliberately list alternative functions, then test which idea is feasible and supported by evidence.'},
8:{0:'Example: compare predicted and measured deflection of a beam under a stated load, documenting material properties, boundary conditions and uncertainty.',1:'Example: test how temperature changes a reaction yield while holding other operating conditions constant, then compare measurements with a process model.',2:'Example: evaluate a bridge-material choice using load requirements, site conditions, durability and a clearly stated safety margin.',3:'Example: compare two algorithms on the same documented dataset using the same evaluation metric and baseline.',4:'Example: compare two prototype designs against pre-defined cost, reliability, usability and performance criteria.',5:'Example: use interviews or archival sources to investigate a social question, explaining how participants or documents were selected and interpreted.',6:'Example: compare a heat-transfer design at defined flow rates and temperatures, stating assumptions and measurement uncertainty.',7:'Example: change a material’s processing temperature and measure how the resulting microstructure relates to hardness.',8:'Example: evaluate an offshore component under specified wave and corrosion conditions, separating simulation results from field evidence.',9:'Example: investigate whether a new workplace process changes turnaround time, defining the unit of analysis and considering confounding factors.',10:'Example: compare an aerodynamic design across a stated speed range and explain where the model or test results have been validated.',11:'Example: compare a biological treatment with a suitable control, recording sample conditions and steps used to prevent contamination.',12:'Example: measure reaction outcome under documented reagent concentrations, temperature and instrument settings.',13:'Example: compare a circuit’s measured output with its expected response while accounting for calibration, noise and component tolerances.',14:'Example: state a mathematical conjecture precisely and provide a proof or counterexample rather than treating numerical examples as proof.',15:'Example: compare measured motion with a physical model and state the measurement uncertainty and conditions where the model applies.',16:'Example: summarise a researcher’s question, method choice, setback and response, then identify which lesson is context-specific.'},
11:{2:'Example: turn an experience talk into a timeline of the question, method selected, evidence that changed the plan and the resulting next step.',3:'Example: compare two researchers’ paths and explain how different questions, constraints or disciplines led to different method choices.'},
12:{0:'Example: for a multi-select screenshot question, test every option against the exact wording and explain why each selected option is supported.',1:'Example: trace a research claim from the literature gap through method, observations, analysis and a conclusion with stated limitations.',2:'Example: answer a short mixed quiz without notes, mark uncertain items, then use the original assignment image to verify wording and reasoning.'}
};if(topicExtras[n]&&topicExtras[n][ti])selectedSection=[topic,[...topicExtras[n][ti]],(topicExamples[n]&&topicExamples[n][ti])||selectedSection[2]||w.note||'Use the relevant lecture source to work through a concrete example.'];const sections=sourceSections.map((s,i)=>`<section class="study-section"><div class="study-section-num">${String(i+1).padStart(2,'0')}</div><div class="study-section-body"><h3>${esc(s[0])}</h3><div class="study-bullet-grid">${s[1].map((v,j)=>`<div class="study-bullet-card tone-${(i+j)%6}"><span class="bullet-mark">${String(j+1).padStart(2,"0")}</span><p>${esc(v)}</p></div>`).join('')}</div><div class="example-box"><b>Think it through</b><p>${esc(s[2])}</p></div></div></section>`).join('');const topicList=topics.map((t,i)=>`<button class="topic-select ${i===ti?'active':''}" data-topic-index="${i}"><span class="topic-select-num">${String(i+1).padStart(2,'0')}</span><span>${esc(t)}</span><span class="topic-select-arrow">${i===ti?'●':'↗'}</span></button>`).join('');const beginnerBullets=selectedSection[1].map((v,j)=>`<div class="topic-explain-card tone-${j%6}"><span>${String(j+1).padStart(2,'0')}</span><p>${esc(v)}</p></div>`).join('');return `${title('WEEK '+String(n).padStart(2,'0'),w.title,w.short)}<div class="week-detail-top"><div><span class="source-chip">${esc(w.source)}</span><p class="detail-intro">${esc(d.overview||w.note)}</p><div class="tag-row">${w.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div><div class="detail-actions"><button class="btn btn-primary" data-mark-week="${n}">${completedWeeks().includes(n)?'✓ Completed · undo':'Mark week complete'}</button><button class="btn btn-light" data-cards-week="${n}">Study cards →</button><button class="btn btn-light" data-quiz-week="${n}">Take practice quiz →</button></div></div><section class="topic-explorer" id="topic-explorer"><div class="study-heading"><span>START HERE · TOPIC-BY-TOPIC</span><h2>Every topic in this week</h2><p>Select any topic to open its beginner-friendly explanation. The complete week notes, key facts, self-check and assignment screenshots remain below.</p></div><div class="topic-select-grid">${topicList}</div><article class="topic-expanded"><div class="topic-expanded-head"><div><span class="topic-kicker">TOPIC ${String(ti+1).padStart(2,'0')} OF ${topics.length}</span><h2>${esc(topic)}</h2></div><span class="topic-source">${esc(w.source)}</span></div><div class="topic-overview"><b>OVERVIEW · IN SIMPLE WORDS</b><p><strong>${esc(topic)}</strong> focuses on ${esc((selectedSection[0]||topic).replace(/^\d+\.\s*/,''))}. ${esc((selectedSection[1]||[])[0]||d.overview||w.note)} Use the detailed points and example below to understand the idea, then compare it with the complete week notes and original course source.</p></div><h3 class="topic-subheading">Detailed explanation</h3><div class="topic-explain-grid">${beginnerBullets}</div><div class="topic-example"><b>EXAMPLE / APPLY THE IDEA</b><p>${esc(selectedSection[2]||w.note)}</p></div><div class="topic-exam-tip"><b>HOW TO REVISE THIS TOPIC</b><p>First define the topic without looking. Next explain each point above, work through the example, and contrast it with a related concept. Finally answer the week self-check and assignment questions. For later-week material, use the official course page to confirm lecture-specific details.</p></div></article></section><div class="detail-tabs"><a href="#study-content">▤ Full study content</a><a href="#key-facts">✦ Key facts</a><a href="#self-check">◉ Self-check</a><a href="#assignment-screens">▣ Assignment screenshots</a></div><section class="study-overview" id="study-content"><div class="study-heading"><span>01 / FULL WEEK NOTES</span><h2>Complete study content</h2><p>These existing detailed notes are preserved. Use them to deepen the topic you just studied and connect it to the rest of the week.</p></div>${sections}</section><section class="key-facts-panel" id="key-facts"><div class="study-heading"><span>02 / QUICK RECALL</span><h2>Key facts to remember</h2></div><div class="fact-grid">${(d.key||[]).map((k,i)=>`<div class="fact-item"><span>${String(i+1).padStart(2,'0')}</span><p>${esc(k)}</p></div>`).join('')}</div></section><section class="self-check-panel" id="self-check"><div class="study-heading"><span>03 / CHECK YOUR UNDERSTANDING</span><h2>Can you answer these?</h2><p>Try aloud or in writing before opening the flashcards.</p></div><ol>${(d.check||[]).map(q=>`<li>${esc(q)}</li>`).join('')}</ol><div class="action-row"><button class="btn btn-dark" data-cards-week="${n}">Review study cards →</button><button class="btn btn-primary" data-quiz-week="${n}">Take this week’s quiz →</button></div></section><section class="assignment-embed" id="assignment-screens"><div class="section-head"><div><h2>Assignment screenshots</h2><p>Original screenshots from the uploaded archive for Week ${n}; use these to verify exact question wording.</p></div><button class="text-btn" data-view="assignments">Full archive ↗</button></div>${archiveGallery(n)}</section>`}
function flashcards(){let arr=cards.filter(c=>!state.cardWeek||c.week===state.cardWeek);if(!arr.length)arr=cards;state.filteredCards=arr;state.cardIndex=Math.min(state.cardIndex,arr.length-1);let c=arr[state.cardIndex]||arr[0];return `${title('ACTIVE RECALL','Flashcards','Try to answer before revealing the back. Mark cards as known to track mastery.')}<div class="filters"><button class="filter-btn ${!state.cardWeek?'active':''}" data-card-filter="0">All weeks</button>${weeks.map(w=>`<button class="filter-btn ${state.cardWeek===w.n?'active':''}" data-card-filter="${w.n}">W${w.n}</button>`).join('')}</div><div class="flash-layout"><section class="flashcard-wrap"><div class="flash-meta"><span>WEEK ${c.week} · ${c.tag}</span><span>Card ${state.cardIndex+1} of ${arr.length}</span></div><div class="flash-face" id="flashFace" role="button" tabindex="0" aria-label="Reveal answer"><div class="eyebrow">${state.showAnswer?'THE ANSWER':'THINK FIRST · THEN REVEAL'}</div><h2>${state.showAnswer?c.a:c.q}</h2>${state.showAnswer?'<p>Say the key idea in your own words before moving on.</p>':'<p>Tap this card or use “Reveal answer” when you are ready.</p>'}</div><div class="flash-controls"><button class="btn btn-light" data-card-nav="prev">← Previous</button><button class="btn btn-dark" data-action="reveal">${state.showAnswer?'Hide answer':'Reveal answer'}</button><button class="btn btn-light" data-card-nav="next">Next →</button></div><div style="display:flex;gap:8px;margin-top:9px"><button class="btn btn-ghost" style="flex:1;justify-content:center" data-card-rate="again">↻ Review again</button><button class="btn btn-primary" style="flex:1;justify-content:center" data-card-rate="know">✓ I know this</button></div></section><aside class="flash-side"><div class="panel"><h3>Your recall progress</h3><p class="panel-desc">Saved locally on this device.</p><div class="small-label">Cards marked known</div><div class="big-number">${(progress.known||[]).length}<span style="font-size:12px;color:#9a9fa6;font-weight:500"> / ${cards.length}</span></div><div class="meter"><span style="width:${Math.min(100,(progress.known||[]).length/cards.length*100)}%"></span></div><p class="panel-desc">Return to missed cards until you can explain the answer without cues.</p></div><div class="panel"><h3>Study tip</h3><p style="font-size:11px;line-height:1.7;color:#7b838d;margin:0">Do not only recognise the answer. Close the card and retrieve it from memory. For process topics, explain the “why” and give an example.</p></div><div class="panel"><h3>Current topic</h3><p class="panel-desc">${weeks.find(w=>w.n===c.week).title}</p><button class="btn btn-light" data-open-week="${c.week}">Open week notes →</button></div></aside></div>`}
function startQuiz(mode='practice',week=0){state.quizMode=mode;let source=mode==='assignment'?assignmentSample:practice;let arr=source.filter(q=>!week||q.week===week);if(!week){arr=[...source].sort(()=>Math.random()-.5)}state.quizItems=arr;state.quizIndex=0;state.answers=[];state.answered=false;state.quizWeek=week;go('quiz')}
function quizPage(mode='practice'){
 let arr=state.quizItems.length?state.quizItems:(mode==='assignment'?assignmentSample:practice);
 if(!state.quizItems.length){state.quizItems=arr;state.quizIndex=0;state.answers=[];state.answered=false}
 if(state.quizIndex>=arr.length)return quizResult();
 const q=arr[state.quizIndex],ans=state.answers[state.quizIndex];
 const multi=Array.isArray(q.correct);
 const selected=multi?(Array.isArray(ans)?ans:[]):(ans===undefined?[]:[ans]);
 const correctSet=multi?q.correct:[q.correct];
 const isCorrect=state.answered&&selected.length===correctSet.length&&selected.every(v=>correctSet.includes(v));
 const label=mode==='assignment'?'UPLOADED ASSIGNMENT QUESTION BANK':'REVISION PRACTICE';
 const titleText=mode==='assignment'?'All assignment questions':'Practice quiz';
 const sub=mode==='assignment'?'120 questions: the prior bank plus the 10-question Week 10 assignment you just supplied. Select every correct option where applicable. The duplicated Week 10/11 screenshot folders are counted once as the visible Week 11 assignment.':'Additional revision questions based on the course topics. These are practice questions, not official assignment questions.';
 return `${title(label,titleText,sub)}<div class="quiz-card"><div class="quiz-top"><span>QUESTION ${state.quizIndex+1} / ${arr.length}</span><span>WEEK ${q.week} · Q${q.num||state.quizIndex+1}</span></div><div class="quiz-progress"><span style="width:${(state.quizIndex+1)/arr.length*100}%"></span></div><div class="question-number">QUESTION ${String(state.quizIndex+1).padStart(2,'0')} ${multi?'<span class="tag">SELECT ALL THAT APPLY</span>':''}</div><div class="question-text">${q.q}</div><div class="options">${q.options.map((o,i)=>`<button class="option ${selected.includes(i)?'selected':''} ${state.answered&&correctSet.includes(i)?'correct':''} ${state.answered&&selected.includes(i)&&!correctSet.includes(i)?'wrong':''}" data-answer="${i}" ${state.answered?'disabled':''}><span class="letter">${multi?(selected.includes(i)?'✓':'□'):String.fromCharCode(65+i)}</span><span>${o}</span></button>`).join('')}</div>${state.answered?`<div class="feedback"><b>${isCorrect?'Correct.':'Review this one.'}</b> ${q.explain||'Compare each option with the relevant course concept.'}<p><b>Answer:</b> ${correctSet.map(i=>q.options[i]).join(' · ')}</p></div>`:''}<div class="quiz-actions"><small>${state.answered?'Answer recorded':multi?'Select every option you believe is correct.':'Choose one option to submit your answer.'}</small>${state.answered?`<button class="btn btn-primary" data-action="next-question">${state.quizIndex===arr.length-1?'See results':'Next question →'}</button>`:`<button class="btn btn-primary" data-action="submit-answer" ${selected.length===0?'disabled':''}>Check answer →</button>`}</div></div><div style="display:flex;justify-content:center;gap:10px;flex-wrap:wrap"><button class="btn btn-ghost" data-view="assignments">Browse assignment screenshots</button><button class="btn btn-ghost" data-action="restart-quiz">Restart set</button></div>`;
}
function quizResult(){let arr=state.quizItems,correct=arr.filter((q,i)=>{const a=state.answers[i];return Array.isArray(q.correct)?Array.isArray(a)&&a.length===q.correct.length&&a.every(v=>q.correct.includes(v)):a===q.correct}).length;return `${title('SESSION COMPLETE','Nice work. Review what you missed.','Use the feedback as a guide, then revisit the matching week before another attempt.')}<div class="quiz-card result-panel"><div class="eyebrow">YOUR SCORE</div><div class="result-score">${correct} / ${arr.length}</div><div class="meter"><span style="width:${correct/arr.length*100}%"></span></div><p>${Math.round(correct/arr.length*100)}% correct. ${correct===arr.length?'Excellent retrieval — try another shuffled set.': 'Review the explanations below and retry the missed topics.'}</p><div style="display:flex;justify-content:center;gap:8px;flex-wrap:wrap;margin:20px 0"><button class="btn btn-primary" data-action="restart-quiz">Try again</button><button class="btn btn-light" data-view="flashcards">Review flashcards</button><button class="btn btn-light" data-view="weeks">Back to weeks</button></div></div><div class="section-head"><div><h2>Answer review</h2><p>Use each explanation to identify what to revisit.</p></div></div><div class="week-list">${arr.map((q,i)=>`<div class="week-row" style="cursor:default"><div class="week-num" style="background:${state.answers[i]===q.correct?'#e8f4ee':'#fff0e4'};color:${state.answers[i]===q.correct?'#317a61':'#a65f33'}">${state.answers[i]===q.correct?'✓':'!'}</div><div><b>${q.q}</b><small>${q.explain}</small></div><span class="status-pill">${state.answers[i]===q.correct?'Correct':'Review'}</span></div>`).join('')}</div>`}
function archiveGallery(n){let path=`assets/assignments/rm_assignments/`;let files=[];for(let i=1;i<=10;i++){let candidates=[`week${n}_${i}.png`,n===6&&i===1?'week6.png':null,n===6&&i===2?'week6_.png':null].filter(Boolean);for(const f of candidates){if(fExists[f])files.push(f)}}if(!files.length)return '<div class="empty">No matching screenshots were indexed for this week. Check the full assignment archive.</div>';return `<div class="image-gallery">${files.map(f=>`<a href="${path+f}" target="_blank"><img loading="lazy" src="${path+f}" alt="Week ${n} assignment screenshot"><span>${f.replace('.png','').replace('_',' · screenshot ')}</span></a>`).join('')}</div>`}
// File names are packaged with the site. This explicit map avoids relying on server-side directory listing.
const fExists={'week10_1.png':true,'week10_2.png':true,'week10_3.png':true,'week11_1.png':true,'week11_10.png':true,'week11_2.png':true,'week11_3.png':true,'week11_4.png':true,'week11_5.png':true,'week11_6.png':true,'week11_7.png':true,'week11_8.png':true,'week11_9.png':true,'week12_1.png':true,'week12_10.png':true,'week12_2.png':true,'week12_3.png':true,'week12_4.png':true,'week12_5.png':true,'week12_6.png':true,'week12_7.png':true,'week12_8.png':true,'week12_9.png':true,'week1_1.png':true,'week1_2.png':true,'week1_3.png':true,'week1_4.png':true,'week1_5.png':true,'week2_1.png':true,'week2_2.png':true,'week2_3.png':true,'week3_1.png':true,'week3_2.png':true,'week3_3.png':true,'week4_1.png':true,'week4_2.png':true,'week4_3.png':true,'week5_1.png':true,'week5_2.png':true,'week5_3.png':true,'week6.png':true,'week6_.png':true,'week6_1.png':true,'week6_2.png':true,'week6_3.png':true,'week6_4.png':true,'week7_1.png':true,'week7_2.png':true,'week7_3.png':true,'week7_4.png':true,'week7_5.png':true,'week7_6.png':true,'week7_7.png':true,'week7_8.png':true,'week8_1.png':true,'week8_2.png':true,'week8_3.png':true,'week8_4.png':true,'week8_5.png':true,'week8_6.png':true,'week9_1.png':true,'week9_10.png':true,'week9_2.png':true,'week9_3.png':true,'week9_4.png':true,'week9_5.png':true,'week9_6.png':true,'week9_7.png':true,'week9_8.png':true,'week9_9.png':true};
function assignments(){return `${title('YOUR UPLOADED MATERIAL','Assignment archive','Browse the assignment screenshots for all 12 folders. Original wording is preserved; use screenshots as the authority for course-specific questions.')}<div class="notice"><b>Combined question bank:</b> 120 assignment questions are available in Practice Quiz, including multi-select items. The Week 10 assignment is now included from the additional screenshots you supplied; it contains 10 questions. Some text was reconstructed where OCR was imperfect; compare against the original images when wording looks unclear.</div><div class="archive-grid">${weeks.map(w=>{let count=Object.keys(fExists).filter(f=>f.startsWith(`week${w.n}_`)||(w.n===6&&(f==='week6.png'||f==='week6_.png'))).length;return `<article class="archive-card"><div class="week-card-top"><span class="week-badge">WEEK ${String(w.n).padStart(2,'0')}</span><span class="muted" style="font-size:10px">${count} image names</span></div><h3>${w.title}</h3><p>${w.n===1?'10 questions in combined bank.':w.n===10?'10 questions transcribed from the additional Week 10 screenshots you supplied.':w.n===12?'Week 12 assignment topics included; lecture title not verified.':'Questions included in the combined assignment bank.'}</p><button class="btn btn-light" data-archive-week="${w.n}">View screenshots →</button></article>`}).join('')}</div><div class="section-head"><div><h2>Combined assignment question bank</h2><p>All transcribed assignment questions are available through the combined quiz.</p></div><button class="text-btn" data-action="assignment-quiz">Start all assignment questions →</button></div><div class="week-list">${assignmentSample.slice(0,6).map((q,i)=>`<div class="week-row" style="cursor:default"><div class="week-num">${String(i+1).padStart(2,'0')}</div><div><b>${q.q}</b><small>${q.options.join(' · ')}</small></div><span class="status-pill current">In bank</span></div>`).join('')}</div><div id="archiveDisplay"></div>`}
function notes(){let q=(state.search||document.getElementById('globalSearch').value||'').toLowerCase().trim();let items=[];weeks.forEach(w=>{if(!q||(w.title+' '+w.short+' '+w.topics.join(' ')+' '+w.note+' '+w.tags.join(' ')).toLowerCase().includes(q))items.push({title:'Week '+w.n+' · '+w.title,body:w.note,action:`data-open-week="${w.n}"`})});cards.forEach(c=>{if(!q||(c.q+' '+c.a+' '+c.tag).toLowerCase().includes(q))items.push({title:c.q,body:c.a,action:`data-cards-week="${c.week}"`})});return `${title('FIND A CONCEPT','Search notes & cards','Search across the week map, revision notes and flashcard prompts.')}<div class="search-box" style="width:100%;max-width:620px;margin-top:20px"><span>⌕</span><input id="noteSearch" value="${q.replaceAll('"','&quot;')}" placeholder="Try: literature, IP, creativity, generative AI…"></div><div class="search-results">${items.length?items.slice(0,50).map(x=>`<div class="search-result" ${x.action}><b>${x.title}</b><p>${x.body}</p></div>`).join(''):'<div class="empty">No matching topics found. Try a broader term.</div>'}</div><div class="footer-note">The search covers the site’s revision notes and flashcards. It does not perform full-text search inside the PDF files.</div>`}
function render(){updateProgress();if(state.view==='home')content.innerHTML=home();else if(state.view==='weeks')content.innerHTML=weeksPage();else if(state.view==='week-detail')content.innerHTML=weekDetail(state.selectedWeek);else if(state.view==='flashcards')content.innerHTML=flashcards();else if(state.view==='assignments')content.innerHTML=assignments();else if(state.view==='quiz')content.innerHTML=quizPage('assignment');else if(state.view==='assignment-quiz')content.innerHTML=quizPage('assignment');else if(state.view==='notes')content.innerHTML=notes();}
function answer(i){if(state.answered)return;const q=state.quizItems[state.quizIndex];if(Array.isArray(q.correct)){const a=Array.isArray(state.answers[state.quizIndex])?[...state.answers[state.quizIndex]]:[];state.answers[state.quizIndex]=a.includes(i)?a.filter(x=>x!==i):[...a,i]}else{state.answers[state.quizIndex]=i}render()}
function markWeek(n){let a=completedWeeks();progress.weeks=a.includes(n)?a.filter(x=>x!==n):[...a,n];save();render()}
function goToQuiz(mode,week=0){state.quizMode='assignment';let src=assignmentSample;let arr=src.filter(q=>!week||q.week===week);if(!week&&mode==='practice')arr=[...arr];state.quizItems=arr;state.quizIndex=0;state.answers=[];state.answered=false;state.quizWeek=week;state.view='quiz';render();document.getElementById('crumbTitle').textContent='Practice quiz · all assignments';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view==='quiz'))}



// Event delegation is intentionally used so controls keep working after each re-render.
document.addEventListener('click', (event) => {
  const target = event.target.closest('button, [data-view], [data-week], [data-open-week], [data-cards-week], [data-card-filter], [data-card-nav], [data-card-rate], [data-archive-week], [data-topic-index], #flashFace');
  if (!target) return;
  if (target.matches('#flashFace')) { state.showAnswer = !state.showAnswer; render(); return; }
  if (target.matches('#menuBtn')) { document.getElementById('sidebar').classList.toggle('open'); return; }
  if (target.matches('#resetProgress')) {
    if (confirm('Reset saved study progress on this device?')) { progress = {}; save(); render(); }
    return;
  }
  if (target.dataset.view) { go(target.dataset.view); return; }
  if (target.dataset.openWeek) { state.selectedWeek = Number(target.dataset.openWeek); state.selectedTopicIndex = 0; go('week-detail'); return; }
  if (target.dataset.topicIndex !== undefined) { state.selectedTopicIndex = Number(target.dataset.topicIndex); render(); document.getElementById('topic-explorer')?.scrollIntoView({behavior:'smooth',block:'start'}); return; }
  if (target.dataset.week) { state.selectedWeek = Number(target.dataset.week); state.selectedTopicIndex = 0; go('week-detail'); return; }
  if (target.dataset.cardsWeek) { state.cardWeek = Number(target.dataset.cardsWeek); state.cardIndex = 0; state.showAnswer = false; go('flashcards'); return; }
  if (target.dataset.cardFilter !== undefined) { state.cardWeek = Number(target.dataset.cardFilter); state.cardIndex = 0; state.showAnswer = false; render(); return; }
  if (target.dataset.cardNav) {
    const arr = state.filteredCards || cards;
    state.cardIndex = target.dataset.cardNav === 'next' ? (state.cardIndex + 1) % arr.length : (state.cardIndex - 1 + arr.length) % arr.length;
    state.showAnswer = false; render(); return;
  }
  if (target.dataset.cardRate) {
    const c = (state.filteredCards || cards)[state.cardIndex];
    progress.known = progress.known || [];
    if (target.dataset.cardRate === 'know' && !progress.known.includes(c.id)) progress.known.push(c.id);
    if (target.dataset.cardRate === 'again') progress.known = progress.known.filter(id => id !== c.id);
    save();
    state.cardIndex = (state.cardIndex + 1) % (state.filteredCards || cards).length;
    state.showAnswer = false; render(); return;
  }
  if (target.dataset.archiveWeek) {
    state.archiveWeek = Number(target.dataset.archiveWeek);
    const display = document.getElementById('archiveDisplay');
    if (display) { display.innerHTML = `<div class="section-head"><div><h2>Week ${state.archiveWeek} screenshots</h2><p>Open any image to inspect the original assignment wording.</p></div></div>${archiveGallery(state.archiveWeek)}`; display.scrollIntoView({behavior:'smooth',block:'start'}); }
    return;
  }
  if (target.dataset.answer !== undefined) { answer(Number(target.dataset.answer)); return; }
  const action = target.dataset.action;
  if (action === 'start') { go('weeks'); return; }
  if (action === 'reveal') { state.showAnswer = !state.showAnswer; render(); return; }
  if (action === 'submit-answer') { state.answered = true; render(); return; }
  if (action === 'next-question') { state.quizIndex += 1; state.answered = false; render(); return; }
  if (action === 'restart-quiz') { const mode = state.quizMode || 'assignment'; startQuiz(mode, state.quizWeek || 0); return; }
  if (action === 'assignment-quiz') { startQuiz('assignment'); return; }
});
document.addEventListener('input', (event) => {
  if (event.target.id === 'globalSearch' || event.target.id === 'noteSearch') {
    state.search = event.target.value;
    if (event.target.id === 'globalSearch') { state.view = 'notes'; document.querySelectorAll('.nav-item').forEach(b => b.classList.toggle('active',b.dataset.view==='notes')); document.getElementById('crumbTitle').textContent='Search notes'; }
    render();
    const input = document.getElementById('noteSearch');
    if (input && event.target.id === 'globalSearch') { input.focus(); input.setSelectionRange(input.value.length,input.value.length); }
  }
});
document.addEventListener('keydown', (event) => {
  if ((event.key === 'Enter' || event.key === ' ') && event.target.id === 'flashFace') { event.preventDefault(); state.showAnswer = !state.showAnswer; render(); }
});
document.getElementById('globalSearch').addEventListener('keydown', (event) => { if (event.key === 'Enter') { state.search = event.target.value; go('notes'); }});
render();
